        // Fetch initial data
        this.fetchData();
    };

    this.onAccountChange = (event) => {
        this.accountId = event.target.value;
        this.fetchData();
    };

    this.onEditContact = (contact) => {
        // Navigate to edit contact page
        const url = `/lightning/r/Contact/${contact.Id}/edit?retURL=%2Flightning%2FrecordList%2F${this.accountId}`;
        window.open(url);
    };

    fetchData() {
        // Fetch contacts for the selected account
        const action = this.createAction('c.getContacts', { accountId: this.accountId });
        action.setCallback(this, function(response) {
            const state = response.getState();
            if (state === 'SUCCESS') {
                this.contacts = response.getReturnValue();
            } else {
                console.error('Error fetching contacts: ', response.getError());
            }
        });
        $A.enqueueAction(action);
    }
}
