Sure! Here's a simple JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(' ');

  // Filter out the adjectives (words that end with -ly or are part of a hyphenated word)
  const adjectives = words.filter(word => /\b(?![a-z]{2,}\-)[a-z]+(-[a-z]+)?\b/.test(word));

  // Reverse the order of the adjectives
  const reversedAdjectives = adjectives.reverse();

  // Join the reversed adjectives back into a sentence
  const result = reversedAdjectives.join(' ') + ' ' + words.filter(word => !/^[a-z]+(-[a-z]+)?$/.test(word)).join(' ');

  return result;
}

// Test the function with your example sentence
