func processUserInput(clickHistory: [String], colorPreferences: [String], productReviews: [String]) -> String {
    // Tokenize user input
    let tokenizer = NLTokenizer(string: clickHistory + colorPreferences + productReviews, unitType: .word)
    tokenizer.enumerateSubstringsInRange(tokenizer.startIndex..<tokenizer.endIndex, unit: .word, scheme: .utf8) { token in
        print("Token: \(token.range.location) - \(token.range.length), Text: \(token.rawString)")
    }

    // Perform sentiment analysis
    let sentimentAnalyzer = NLSentimentAnalysis()
    let sentimentScore = sentimentAnalyzer.sentimentScore(for: "positive", in: clickHistory + colorPreferences + productReviews)
    print("Sentiment score: \(sentimentScore)")

    // Generate personalized statement
    let statement = "Based on your click history, color preferences, and product reviews, we recommend the following products:\n\(productReviews.prefix(3).joined(separator: "\n"))"
    return statement
}
```

