function tense = identify_tense(sentence)
    % Regular expression pattern to match different tenses
    pattern = '(?i)(?:^|\s+)(present|past|future)\b';

    % Match the tense in the sentence using regular expression
    match = regexp(sentence, pattern, 'match');

    % Extract the matched tense from the regular expression result
    tense = match{1};
end

