Here's an example of a Generic REST Service Wrapper Class in C# with Auth Token Handling:
```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class RestServiceWrapper<T>
{
    private readonly string _apiUrl;
    private readonly string _authToken;

    public RestServiceWrapper(string apiUrl, string authToken)
    {
        _apiUrl = apiUrl;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync(_apiUrl);
            if (response.IsSuccessStatusCode)
            {
                return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
            }
            else
            {
                throw new Exception($"Failed to fetch data from API: {response.StatusCode} - {response.ReasonPhrase}");
            }
        }
    }
}
```
