Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value matches the string key:

```javascript
function getObjectEntries(object, keyPath) {
  const keys = keyPath.split('.');
  let currentObject = object;

  for (const key of keys) {
    if (!currentObject[key]) {
      return [];
    }
    currentObject = currentObject[key];
  }

  return Object.entries(currentObject);
}

// Example usage
const object = {
  a: {
    b: 'c',
    d: 'e',
  },
  f: 'g',
};

const keyPath = 'a.b';
const result = getObjectEntries(object, keyPath);
console.log(result); // Output: [['b', 'c']]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getObjectEntries(obj, key) {
  const keys = key.split(".");
  const result = [];

  function traverse(obj, keys) {
    if (keys.length === 0) {
      result.push(obj);
      return;
    }

    const key = keys.shift();
    if (obj[key] !== undefined) {
      traverse(obj[key], keys);
    }
  }

  traverse(obj, keys);
  return result;
}
```

You can use this function like this:

