function getMatchingEntries(obj, str) {
  const entries = [];

  Object.entries(obj).forEach(([key, value]) => {
    if (key === str || obj[str] === value) {
      entries.push({ key, value });
    } else if (typeof value === 'object') {
      entries.push(...getMatchingEntries(value, str));
    }
  });

  return entries;
}

