Here's a Go program that parses a struct in a Go source file and generates a Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/v2/schema"
)

func main() {
	sourceFile := "example.go"
	structName := "MyStruct"
	outputFile := "struct.avsc"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Println("Error reading source file:", err)
		return
	}

	re := regexp.MustCompile(`type (\w+) struct`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		fmt.Println("Unable to find struct definition in source file")
		return
	}

	structType := matches[1]

	fields := []schema.Field{}

	// Parse the struct fields
	for _, field := range strings.Split(content, "\n") {
		if strings.HasPrefix(field, fmt.Sprintf("%s ", structType)) {
			parts := strings.Fields(field)
			if len(parts) >= 2 {
				fieldName := parts[1]
				fieldType := parts[2]
				fields = append(fields, schema.Field{Name: fieldName, Type: schema.ParseType(fieldType)})
			}
		}
	}

	schemaDef := schema.NewSchema(structName, fields)
	err = schemaDef.Validate()
	if err != nil {
		fmt.Println("Error validating schema:", err)
		return
	}

	err = ioutil.WriteFile(outputFile, []byte(schemaDef.ToString()), 0644)
	if err != nil {
		fmt.Println("Error writing output file:", err)
		return
