```php
<?php
// Database connection details
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "database_name";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Query to retrieve customer information and purchase history
$sql = "SELECT c.name, c.email, p.product_name, COUNT(p.product_id) AS purchase_count
FROM customers c
JOIN purchases p ON c.customer_id = p.customer_id
WHERE p.product_name = 'specific product' AND p.date BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 WEEK) AND CURDATE()
GROUP BY c.name, c.email, p.product_name
HAVING purchase_count >= 3";

// Execute query
$result = $conn->query($sql);

// Display results
if ($result->num_rows > 0) {
    // output data of each row
    while($row = $result->fetch_assoc()) {
        echo "Name: " . $row["name"]. " - Email: " . $row["email"]. " - Product Name: " . $row["product_name"]. " - Purchase Count: " . $row["purchase_count"]. "<br>";
    }
} else {
    echo "0 results";
}

// Close connection
$conn->close();
?>
```

