To create a simple toast notification using React Context, follow these steps:

1. Create a `NotificationContext` file:

```javascript
import React from 'react';

const NotificationContext = React.createContext({});

function NotificationProvider(props) {
  const [notifications, setNotifications] = React.useState([]);

  function addNotification(notification) {
    setNotifications((prevNotifications) => [...prevNotifications, notification]);
  }

  return (
    <NotificationContext.Provider value={{ notifications, addNotification }}>
      {props.children}
    </NotificationContext.Provider>
  );
}

export { NotificationContext, NotificationProvider };
```

2. In your main application component, wrap your content with the `NotificationProvider`:

```javascript
import React from 'react';
import NotificationContext from './NotificationContext';

function App() {
  return (
    <NotificationContext.Provider value={{ notifications: [], addNotification: () => {} }}>
      {/* Your app content goes here */}
    </NotificationContext.Provider>
  );
}

export default App;
```

3. Now, you can use the `NotificationContext` in any child component to display a toast notification. For example:

```javascript
import React, { useState } from 'react';
import { useContext } from 'react';
import NotificationContext from './NotificationContext';

function MyComponent() {
  const { notifications, addNotification } = useContext(NotificationContext);

  function handleClick() {
    addNotification({
      title: 'Notification Title',
      message: 'Notification message',
      duration: 3000, // milliseconds
    });
  }

  return (
    <div>
      <button onClick={handleClick}>Add Notification</button>
      {notifications.map((notification) => (
        <div key={notification.id}>
          <h2>{notification.title}</h2>
          <p>{notification.message}</p>
        </div>
      ))}
    </div>
  );
}

export default MyComponent;
```

