Sure! Here are four methods to open/close the camera and microphone in JavaScript using the MediaStream API:

1. **Open Camera**:

```javascript
function openCamera() {
  navigator.mediaDevices.getUserMedia({ video: true })
    .then(stream => {
      // Use the stream for video purposes
    })
    .catch(error => console.error('Error opening camera:', error));
}
```

2. **Close Camera**:

```javascript
function closeCamera() {
  const streams = navigator.mediaDevices.enumerateDevices();
  const videoDevice = streams.find(device => device.kind === 'videoinput');

  if (videoDevice) {
    videoDevice.stop();
  }
}
```

3. **Open Microphone**:

```javascript
function openMicrophone() {
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then(stream => {
      // Use the stream for audio purposes
    })
    .catch(error => console.error('Error opening microphone:', error));
}
```

4. **Close Microphone**:

```javascript
function closeMicrophone() {
  const streams = navigator.mediaDevices.enumerateDevices();
  const audioDevice = streams.find(device => device.kind === 'audioinput');

  if (audioDevice) {
    audioDevice.stop();
  }
}
```

