function toggleCamera() {
  const stream = window.stream;
  if (stream) {
    stream.getVideoTracks().forEach(track => track.enabled = !track.enabled);
  } else {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(stream => {
        window.stream = stream;
