```typescript
import * as Chart from 'chart.js';

interface Dataset {
  label: string;
  data: number[];
  backgroundColor?: string[];
  borderColor?: string[];
  borderWidth?: number;
}

function generateBarChart(dataset: Dataset) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  const chartOptions = {
    type: 'bar',
    data: {
      labels: dataset.label,
      datasets: [
        {
          label: dataset.label,
          data: dataset.data,
          backgroundColor: dataset.backgroundColor || ['rgba(255, 99, 132, 0.2)', 'rgba(54, 162, 235, 0.2)', 'rgba(255, 206, 86, 0.2)'],
          borderColor: dataset.borderColor || ['rgba(255, 99, 132, 1)', 'rgba(54, 162, 235, 1)', 'rgba(255, 206, 86, 1)'],
          borderWidth: dataset.borderWidth || 1
        }
      ]
    },
    options: {
      scales: {
        y: {
          beginAtZero: true
        }
      }
    }
  };

  Chart.js.renderChart(canvas, chartOptions);

  return canvas;
}

// Example usage
