      ringNoise: 0.3 * scale,
    };

    // Check if planet is too close to any existing planet
    const tooClose = planets.some((p) =>
      p.position.some((coord, index) => {
        return Math.abs(coord - planet.position[index]) < minDistance;
      })
    );

    if (!tooClose) {
      planets.push(planet);
    } else {
      console.log("Planet too close, generating new coordinates...");
    }
  }

  return planets;
};
```
This function will keep generating new random coordinates until it finds a non-colliding position for the new planet. This should help prevent the planets from being too close together and improve the overall layout of your scene.

