const http = require('http');
const express = require('express');
const app = express();
const server = http.createServer(app);
const io = require('socket.io')(server);

const port = process.env.PORT || 3000;

server.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

app.use(express.json());

// Define the chat rooms
const chatRooms = {};

// Handle incoming connections
io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // Join the user to a chat room
  socket.on('join', (roomId) => {
    if (!chatRooms[roomId]) {
      chatRooms[roomId] = [];
    }
    chatRooms[roomId].push(socket.id);
    socket.join(roomId);

    // Emit a message to all users in the room
    socket.broadcast.to(roomId).emit('join', socket.id);
  });

  // Handle incoming messages
  socket.on('message', (roomId, message) => {
    if (chatRooms[roomId]) {
      chatRooms[roomId].forEach((userId) => {
        if (userId !== socket.id) {
          socket.broadcast.to(userId).emit('message', roomId, message);
        }
      });
    }
  });

  // Handle disconnections
  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket

