```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "no", "none", "nothing"}

func isDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotBeforeNegativeWord(word) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if strings.ToLower(negWord) == strings.ToLower(word) {
			return true
		}
	}
	return false
}

func containsNotBeforeNegativeWord(word string) bool {
