Here's a PowerShell script that recursively checks folders for ACLs referring to SIDs in the SIDHistory of users or groups in the domain:

```powershell
# Define the folder path to start with
$folderPath = "C:\YourFolderPath"

# Function to check if an ACL refers to a SID in the SIDHistory
function CheckACL($acl) {
    $sidHistory = @()

    # Iterate through each access control entry (ACE) in the ACL
    foreach ($ace in $acl) {
        # Check if the ACE refers to a SID in the SIDHistory
        if ($ace.IdentityReference -match '^S-1-5-21-(\d+)-(\d+)-(\d+)-(\d+)$') {
            $sidHistory += $ace.IdentityReference
        }
    }

    # Return true if any SIDs in the SIDHistory are present in the domain
    return ($sidHistory | ForEach-Object { Get-ADUser -Filter { SamAccountName -eq $_ } }) -ne $null
}

# Recursively check folders for ACLs referring to SIDs in the SIDHistory
function CheckFolders($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        if (CheckACL($acl)) {
            Write-Host "Folder: $($_.FullName)"
            CheckFolders($_.FullName)
        }
    }
}

# Start checking folders
CheckFolders($folderPath)
```

