# Define the function to check ACLs for SIDHistory references
function CheckACLsForSIDHistory($folderPath) {
    # Get the folder's ACLs
    $acl = (Get-Acl -Path $folderPath).Access

    # Loop through each access control entry (ACE)
    foreach ($ace in $acl) {
        # Check if the ACE refers to a SID in the SIDHistory of a user or group in the domain
        if ($ace.IdentityReference -match '^S-1-5-21-(\d+)-(\d+)-(\d+)-(\d+)$') {
            # Extract the SID from the ACE
            $sid = $ace.IdentityReference

            # Check if the SID is in the SIDHistory of a user or group in the domain
            $domain = (Get-ADDomain -Filter {Name -eq "your_domain_name"} -Properties DomainMode).DomainMode
            if ($domain -eq "Windows2008" -or $domain -eq "Windows2012") {
                $sidHistory = Get-ADUser -Filter {SamAccountName -eq "$(Get-ADUser -Filter {Sid -eq $sid} -Properties SamAccountName).SamAccountName"} -Properties SIDHistory
                if ($sidHistory) {
                    Write-Host "The ACE for $folderPath references a SID ($sid) in the SIDHistory of a user or group in the domain."
                }
            }
        }
    }
}

# Define the root folder to start checking
$rootFolder = "C:\Your_Root_Folder"

# Recursively check the folders and subfolders
Get-ChildItem -Path $rootFolder -Directory | ForEach-Object {
    CheckACLsForSIDHistory($_)
}
```

